<?php
require "db.php";require "functions.php";need_role("staff");$id=(int)$_SESSION["user_id"];
$q=$pdo->prepare("SELECT id,title,category,description,location,priority,status,resolution_note,created_at FROM complaints WHERE assigned_staff_id=? ORDER BY FIELD(priority,'Urgent','High','Medium','Low'),created_at DESC");$q->execute([$id]);$rows=$q->fetchAll();
$title="Staff workspace";require "layout.php";?>
<div class="page-heading"><div><div class="eyebrow">STAFF WORKSPACE</div><h1>Your assigned <span class="green">work.</span></h1><p>Only complaints assigned to your account are shown.</p></div><span class="pill">Approved staff</span></div>
<div class="stat-grid three"><div class="stat-card"><small>Assigned reports</small><strong><?=count($rows)?></strong><span>Assigned to you</span></div><div class="stat-card"><small>In progress</small><strong><?=count(array_filter($rows,fn($r)=>$r["status"]==="In Progress"))?></strong><span>Being worked on</span></div><div class="stat-card"><small>Resolved</small><strong><?=count(array_filter($rows,fn($r)=>$r["status"]==="Resolved"))?></strong><span>Completed</span></div></div>
<section class="panel"><div class="panel-heading"><div><h2>Assigned complaints</h2><p>Student names and emails are not displayed.</p></div><input class="search" type="search" placeholder="Search reports..." data-filter="staff-table"></div><?php if(!$rows):?><div class="empty"><h3>All clear for now</h3><p>No complaints have been assigned to you yet.</p></div><?php else:?><div class="table-wrap"><table id="staff-table"><thead><tr><th>Complaint</th><th>Priority</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r["title"])?></b><div class="muted small">#<?= (int)$r["id"]?> · <?=e($r["category"])?> · <?=e($r["location"]?: "No location")?></div><p class="table-desc"><?=e($r["description"])?></p></td><td><?=e($r["priority"])?></td><td><?=status_badge($r["status"])?></td><td><form class="form compact" method="post" action="staff_update.php"><input type="hidden" name="csrf_token" value="<?=e(csrf())?>"><input type="hidden" name="complaint_id" value="<?=(int)$r["id"]?>"><select name="status"><?php foreach(["Assigned","In Progress","Resolved"] as $s):?><option <?=($r["status"]===$s?"selected":"")?>><?=e($s)?></option><?php endforeach;?></select><input name="resolution_note" maxlength="2000" placeholder="Add an update" value="<?=e($r["resolution_note"]??"")?>"><button class="btn btn-primary btn-small">Save</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php require "end.php";?>
